        END IF;
    END IF;

    IF NEW.payment_type = 'نەقد' THEN
        SELECT name INTO v_customer_name FROM customers WHERE id = NEW.customer_id;
        SELECT name INTO v_formula_name FROM concrete_formulas WHERE id = NEW.formula_id;

        IF NEW.amount_paid_usd > 0 THEN
            SET v_reference_tag = CONCAT(' [REF:SALE#', NEW.id, '#USD]');
            SET v_note_text = CONCAT(
                'فرۆشتن | ',
                'ژمارەی پسووڵە: ', NEW.invoice_number, ' | ',
                'کڕیار: ', IFNULL(v_customer_name, 'نەناسراو'), ' | ',
                'وەرگر: ', IFNULL(NEW.recipient, '-'), ' | ',
                'شوێن: ', IFNULL(NEW.location, '-'), ' | ',
                'فۆرمۆلا: ', IFNULL(v_formula_name, '-'), ' | ',
                'بڕ: ', IFNULL(NEW.quantity, 0), ' م³ | ',
                'نرخی یەکە: $', IFNULL(NEW.price_per_unit, 0), ' | ',
                'کۆی نرخ: $', IFNULL(NEW.total_price, 0), ' | ',
                'پارەی دراو: $', NEW.amount_paid_usd, ' | ',
                'پارەی ماوە: $', IFNULL(NEW.remaining_amount, 0)
            );
            IF NEW.notes IS NOT NULL AND NEW.notes != '' THEN
                SET v_note_text = CONCAT(v_note_text, ' | تێبینی: ', NEW.notes);
            END IF;
            SET v_note_text = CONCAT(v_note_text, v_reference_tag);

            VALUES (NEW.order_date, 'deposit', 0, NEW.amount_paid_usd, 'دۆلار', v_note_text, NULL);
        END IF;

        IF NEW.amount_paid_iq > 0 THEN
            SET v_reference_tag = CONCAT(' [REF:SALE#', NEW.id, '#IQD]');
            SET v_note_text = CONCAT(
                'فرۆشتن | ',
                'ژمارەی پسووڵە: ', NEW.invoice_number, ' | ',
                'کڕیار: ', IFNULL(v_customer_name, 'نەناسراو'), ' | ',
                'وەرگر: ', IFNULL(NEW.recipient, '-'), ' | ',
                'شوێن: ', IFNULL(NEW.location, '-'), ' | ',
                'فۆرمۆلا: ', IFNULL(v_formula_name, '-'), ' | ',
                'بڕ: ', IFNULL(NEW.quantity, 0), ' م³ | ',
                'نرخی یەکە: ', IFNULL(NEW.price_per_unit, 0), ' د.ع | ',
                'کۆی نرخ: ', IFNULL(NEW.total_price, 0), ' د.ع | ',
                'پارەی دراو: ', NEW.amount_paid_iq, ' د.ع | ',
                'پارەی ماوە: ', IFNULL(NEW.remaining_amount, 0), ' د.ع'
            );
            IF NEW.notes IS NOT NULL AND NEW.notes != '' THEN
                SET v_note_text = CONCAT(v_note_text, ' | تێبینی: ', NEW.notes);
            END IF;
            SET v_note_text = CONCAT(v_note_text, v_reference_tag);

            VALUES (NEW.order_date, 'deposit', NEW.amount_paid_iq, 0, 'دینار', v_note_text, NULL);
        END IF;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_log_material_usage_insert` AFTER INSERT ON `sales` FOR EACH ROW BEGIN
    DECLARE v_black_sand_kg   DECIMAL(10,2);
    DECLARE v_brown_sand_kg   DECIMAL(10,2);
    DECLARE v_gravel_bin3_kg  DECIMAL(10,2);
    DECLARE v_gravel_bin4_kg  DECIMAL(10,2);
    DECLARE v_cement_cem1_kg  DECIMAL(10,2);
    DECLARE v_cement_cem2_kg  DECIMAL(10,2);
    DECLARE v_additive_kg     DECIMAL(10,2);

    -- ڕێژەکانی فۆرمۆلای کاتی داخڵکردن بخوێنە
    SELECT 
        black_sand_kg,
        brown_sand_kg,
        gravel_bin3_kg,
        gravel_bin4_kg,
        cement_cem1_kg,
        cement_cem2_kg,
        additive_kg
    INTO
        v_black_sand_kg,
        v_brown_sand_kg,
        v_gravel_bin3_kg,
        v_gravel_bin4_kg,
        v_cement_cem1_kg,
        v_cement_cem2_kg,
        v_additive_kg
    FROM concrete_formulas
    WHERE id = NEW.formula_id;

    -- گونجاندنی ڕێژەکان بە قەبارەی sale (متر سێجا)
    SET v_black_sand_kg  = IFNULL(v_black_sand_kg,  0) * NEW.quantity;
    SET v_brown_sand_kg  = IFNULL(v_brown_sand_kg,  0) * NEW.quantity;
    SET v_gravel_bin3_kg = IFNULL(v_gravel_bin3_kg, 0) * NEW.quantity;
    SET v_gravel_bin4_kg = IFNULL(v_gravel_bin4_kg, 0) * NEW.quantity;
    SET v_cement_cem1_kg = IFNULL(v_cement_cem1_kg, 0) * NEW.quantity;
    SET v_cement_cem2_kg = IFNULL(v_cement_cem2_kg, 0) * NEW.quantity;
    SET v_additive_kg    = IFNULL(v_additive_kg,    0) * NEW.quantity;

    -- تۆماری snapshot بۆ sale_materials
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_log_material_usage_update` AFTER UPDATE ON `sales` FOR EACH ROW BEGIN
    DECLARE v_black_sand_kg   DECIMAL(10,2);
    DECLARE v_brown_sand_kg   DECIMAL(10,2);
    DECLARE v_gravel_bin3_kg  DECIMAL(10,2);
    DECLARE v_gravel_bin4_kg  DECIMAL(10,2);
    DECLARE v_cement_cem1_kg  DECIMAL(10,2);
    DECLARE v_cement_cem2_kg  DECIMAL(10,2);
    DECLARE v_additive_kg     DECIMAL(10,2);

    -- سڕینەوەی snapshot ـە کۆنەکان بۆ ئەم sale ـە
    DELETE FROM sale_materials WHERE sale_id = NEW.id;

    -- ڕێژەکانی فۆرمۆلای نوێ بخوێنە
    SELECT 
        black_sand_kg,
        brown_sand_kg,
        gravel_bin3_kg,
        gravel_bin4_kg,
        cement_cem1_kg,
        cement_cem2_kg,
        additive_kg
    INTO
        v_black_sand_kg,
        v_brown_sand_kg,
        v_gravel_bin3_kg,
        v_gravel_bin4_kg,
        v_cement_cem1_kg,
        v_cement_cem2_kg,
        v_additive_kg
    FROM concrete_formulas
    WHERE id = NEW.formula_id;

    SET v_black_sand_kg  = IFNULL(v_black_sand_kg,  0) * NEW.quantity;
    SET v_brown_sand_kg  = IFNULL(v_brown_sand_kg,  0) * NEW.quantity;
    SET v_gravel_bin3_kg = IFNULL(v_gravel_bin3_kg, 0) * NEW.quantity;
    SET v_gravel_bin4_kg = IFNULL(v_gravel_bin4_kg, 0) * NEW.quantity;
    SET v_cement_cem1_kg = IFNULL(v_cement_cem1_kg, 0) * NEW.quantity;
    SET v_cement_cem2_kg = IFNULL(v_cement_cem2_kg, 0) * NEW.quantity;
    SET v_additive_kg    = IFNULL(v_additive_kg,    0) * NEW.quantity;

END
$$
DELIMITER ;

