INSERT INTO `unit_conversion_rules` (`id`, `unit_type_id`, `rule_name`, `rule_description`, `conversion_logic`, `is_active`, `created_at`) VALUES
(1, 1, 'carton_to_pieces', 'Convert carton to pieces', '{\"formula\": \"carton_quantity * pieces_per_carton\", \"input_fields\": [\"pieces_per_carton\"], \"output_fields\": [\"total_pieces\"]}', 1, '2025-08-02 20:14:23'),
(2, 2, 'piece_direct', 'Direct piece conversion', '{\"formula\": \"piece_quantity\", \"input_fields\": [], \"output_fields\": [\"total_pieces\"]}', 1, '2025-08-02 20:14:23'),
(3, 3, 'barrel_to_buckets_to_liters', 'Convert barrel to buckets to liters', '{\"formula\": \"barrel_quantity * buckets_per_barrel * liters_per_bucket\", \"input_fields\": [\"buckets_per_barrel\", \"liters_per_bucket\"], \"output_fields\": [\"total_buckets\", \"total_liters\"]}', 1, '2025-08-02 20:14:23'),
(4, 4, 'bucket_to_liters', 'Convert bucket to liters', '{\"formula\": \"bucket_quantity * liters_per_bucket\", \"input_fields\": [\"liters_per_bucket\"], \"output_fields\": [\"total_liters\"]}', 1, '2025-08-02 20:14:23'),
(5, 5, 'liter_direct', 'Direct liter conversion', '{\"formula\": \"liter_quantity\", \"input_fields\": [], \"output_fields\": [\"total_liters\"]}', 1, '2025-08-02 20:14:23');
