(2, 'piece', 'دانە', 'دانە بەتەنیا', 1, '2025-08-02 20:14:23'),
(3, 'barrel', 'بەرمیل', 'بەرمیل کە هەر بەرمیلێک چەند دەبەیە و هەر دەبەیەک چەن لیتر', 1, '2025-08-02 20:14:23'),
(4, 'bucket', 'دەبە', 'دەبە بەتەنیا و هەر دەبەیەک چەن لیتر', 1, '2025-08-02 20:14:23'),
(5, 'liter', 'لیتر', 'لیتر بە تەنیا', 1, '2025-08-02 20:14:23');
